parameters.jsCode:
/**
 * 计算文章的最终AI评分。
 * 此代码片段假定上一个节点（LLM/AI节点）的输出格式为：
 * { "text": "包含JSON评分的文本..." }
 * 并从名为 '拆分文章列表' 的节点获取原始文章数据。
 */

// 从当前节点的直接输入中获取LLM的响应数据
// 正确的方式是使用 $input.item.json
const llmResponse = $input.item.json;

// 从工作流中名为 '拆分文章列表' 的节点获取原始文章数据。
// 请确保 '拆分文章列表' 是您工作流中实际的节点名称。
const originalArticle = $('拆分文章列表').item.json;

// 初始化评分变量
let scores;
try {
  // 从LLM响应中安全地获取文本内容
  const responseText = llmResponse.text || '';

  // 使用正则表达式从文本中安全地提取出JSON对象字符串
  const jsonMatch = responseText.match(/\{[\s\S]*?\}/);

  if (jsonMatch && jsonMatch[0]) {
    // 解析提取到的JSON字符串
    scores = JSON.parse(jsonMatch[0]);
  } else {
    // 如果在响应中找不到JSON，则抛出错误，以便在catch块中处理
    throw new Error('在LLM响应中未找到有效的JSON内容。');
  }
} catch (error) {
  // 如果解析失败或找不到JSON，则在控制台记录错误并使用默认分数，以保证工作流可以继续运行
  console.error(`评分解析失败: ${error.message}. 将使用默认分数。`);
  scores = {
    novelty_score: 5.0,
    impact_score: 5.0,
    clarity_score: 5.0,
    depth_score: 5.0
  };
}

// 根据权重计算加权分数
const weighted_score = 
  (scores.novelty_score * 0.3) +
  (scores.impact_score * 0.4) +
  (scores.clarity_score * 0.1) +
  (scores.depth_score * 0.2);

// 计算最终得分并四舍五入到小数点后两位
const ai_score = Math.round(weighted_score * 100) / 100;

// 返回一个包含所有原始数据和计算出的ai_score的对象，以供后续节点使用
return {
  id: originalArticle.id,
  content: originalArticle.content,
  created_at: originalArticle.created_at,
  ai_score: ai_score,
  novelty_score: scores.novelty_score,
  impact_score: scores.impact_score,
  clarity_score: scores.clarity_score,
  depth_score: scores.depth_score
};

// 目标：将输入的多个文章项（Items）中，
// 只有那些 is_selected_for_morning_news 属性为 true 的数据合并成一个单独的项，
// 以便将所有符合条件的文章内容一次性发送给下一个LLM节点。

// 1. 获取所有输入项 (一个包含多个文章对象的数组)
const inputItems = $input.all();

// 2. 初始化变量，用于存储合并后的数据
let combinedContent = ""; // 用于存储所有文章内容的合并字符串
const articleTitles = [];    // 用于存储所有符合条件文章的标题列表

// 3. 准备日期字符串 (格式: YYYY年MM月DD日)
// 优先使用 n8n 内置的 $now 对象，它更可靠且易于格式化。
// toFormat() 使用 Luxon 格式化标记。'yyyy' 是四位数年份, 'MM' 是两位数月份, 'dd' 是两位数日期。
const selectionDateFormatted = $now.toFormat('yyyy年MM月dd日');

// 4. 构建用于LLM Prompt的核心内容 - 在所有文章内容前添加一个引言
// 注意：这个引言会无条件添加，即使没有文章符合条件。你可以根据需要调整。
combinedContent += `以下是日期为 ${selectionDateFormatted} 的AI新闻精选核心内容：\n\n`;

// 用于跟踪符合条件的文章数量，以便在标题中正确编号
let selectedArticleCount = 0;

// 5. 遍历所有输入项，根据 is_selected_for_morning_news 属性进行筛选并提取信息
inputItems.forEach((item) => {
  const article = item.json;

  // 关键的条件判断：只有当 is_selected_for_morning_news 为 true 时才处理该文章
  if (article.is_selected_for_morning_news === true) { // 确保严格等于 true
    selectedArticleCount++; // 符合条件文章计数增加

    // 为每篇文章添加一个清晰的分隔符和标题
    // 确保编号连续且只针对选中的文章
    combinedContent += `--- 文章 ${selectedArticleCount}: ${article.title || "无标题"} ---\n`;
    // 拼接文章内容，如果内容不存在则使用提示信息
    combinedContent += `${article.content || "内容缺失"}\n\n`;

    // 将文章标题收集到数组中，以备后用
    articleTitles.push(article.title || `无标题文章 ${selectedArticleCount}`);
  }
});

// 6. 准备最终的输出对象
// 这个对象将作为合并后的唯一数据项的内容
const outputData = {
  selection_date: selectionDateFormatted,
  all_articles_content: combinedContent,
  article_titles: articleTitles,
  // 可以添加一个字段来表示有多少文章被选中
  selected_article_count: selectedArticleCount
};

// 7. 返回结果
// 必须返回一个只包含一个元素的数组，这样n8n才会将多个输入项合并为1个输出项。
// 这是将多项流（multi-item stream）转换为单项流（single-item stream）的标准方法。
return [{ json: outputData }]; // 确保返回的是包含一个 json 对象的数组

