/**
 * @description 检查文件写入是否成功
 * 通过检查Execute Command节点的执行结果判断
 * @returns {Object} 包含成功状态和相关信息的对象
 */
function checkWriteSuccess() {
  const writeResult = $json;

  // Execute Command节点成功时会返回执行信息
  const success = writeResult && (writeResult.exitCode === 0 || writeResult.exitCode === undefined);

  return {
    success: success,
    fileName: $('生成早报文章').item.json.fileName,
    articleId: $('生成早报文章').item.json.articleId,
    title: $('生成早报文章').item.json.title,
    filePath: `/app/hugo/hugo/content/morningnews/${$('生成早报文章').item.json.fileName}`,
    error: success ? null : '文件写入失败',
    exitCode: writeResult.exitCode || 0
  };
}

return checkWriteSuccess();

/**
 * 筛选Top 10文章并标记 is_selected_for_morning_news 字段
 * @param {Array} items - 所有已评分的文章数组 (假设每个item包含一个json属性，json属性是文章数据)
 * @returns {Object} - 包含Top 10文章、所有文章（带标记）等信息的对象
 */
const items = $input.all();
const articles = items.map(item => item.json); // 假设输入项的实际文章数据在 'json' 属性中

// 按ai_score降序排序
articles.sort((a, b) => b.ai_score - a.ai_score);

// 选取前10篇文章
const top10Articles = articles.slice(0, 10);

// 获取前10篇文章的ID集合，以便后续高效查找
const top10ArticleIds = new Set(top10Articles.map(article => article.id));

// 为每篇文章添加 is_selected_for_morning_news 标记
const articlesWithMorningNewsSelection = articles.map(article => ({
  ...article,
  // 检查当前文章的ID是否在前10文章的ID集合中
  is_selected_for_morning_news: top10ArticleIds.has(article.id)
}));

// 返回包含Top 10文章的对象以及所有文章（带标记）等信息
return {
  top_10_articles: top10Articles, // 修改键名以反映数量
  all_articles_with_morning_news_selection: articlesWithMorningNewsSelection, // 修改键名以反映字段名
  total_articles: articles.length,
  selection_date: new Date().toISOString()
};

/**
 * 目标：从LLM生成的自定义标签文本中提取信息，
 * 并将其转换为Hugo静态网站生成器所需的Markdown文件格式。
 *
 * 输入：上一个LLM节点传递过来的数据项，格式为 { "text": "<title>...</title>..." }
 *
 * 输出：一个包含hugo_article, fileName等字段的对象。
 */

// --- 1. 数据解析与验证 ---

// 1.1. 定义一个通用的、健壮的标签内容提取函数
const extractTagContent = (tagName, text) => {
  // 使用正则表达式匹配 <tagName>...</tagName> 之间的内容
  // 's' 标志允许 '.' 匹配换行符，确保能处理多行内容
  const regex = new RegExp(`<${tagName}>([\\s\\S]*?)<\\/${tagName}>`, 'i');
  const match = text.match(regex);
  // 如果匹配成功，返回捕获组1的内容并去除首尾空格；否则返回空字符串
  return match ? match[1].trim() : '';
};

// 1.2. 获取并解析LLM输出的文本
const llmOutputText = $input.item.json.text || '';

if (!llmOutputText) {
    throw new Error("从上一个节点接收到的内容为空。");
}

// 1.3. 使用提取函数获取各个字段的内容
const title = extractTagContent('title', llmOutputText);
const articleContentRaw = extractTagContent('article_content', llmOutputText); // 这是完整的早报内容（开篇+列表+总结）
const summary = extractTagContent('summary', llmOutputText); // 这是新的“今日焦点”一句话概括
const tagsString = extractTagContent('tags', llmOutputText);
const mainTopicsString = extractTagContent('main_topics', llmOutputText);


// 1.4. 对提取的核心内容进行健壮性检查
if (!title) {
  // 如果没有标题，后续文件名和Front Matter会出问题，应直接报错
  throw new Error("未能从输入中提取到 <title> 内容。");
}
if (!articleContentRaw) {
  throw new Error("未能从输入中提取到 <article_content> 内容。");
}


// --- 2. 内容格式化 ---

// 2.1. [调整] 对于新的早报格式，LLM应该已经直接输出了Markdown格式的编号列表和文本。
// 不再需要进行小标题的特殊处理，因为LLM输出的 `article_content` 已经包含了最终的Markdown格式。
// 我们可以直接使用 articleContentRaw 作为最终的格式化内容。
const articleContentFormatted = articleContentRaw;

// 2.2. 统计早报中的条目数量（通过匹配编号列表项）
// 假设编号列表项是 "1. ", "2. ", "3. " 这样的格式开始的
const selected_article_count = (articleContentFormatted.match(/^\d+\.\s/gm) || []).length;
// 如果LLM输出的是纯文本，且你希望统计行数作为“条目数”，可以这样：
// const selected_article_count = articleContentFormatted.split('\n').filter(line => line.trim() !== '').length;
// 但根据LLM的输出示例，匹配“1. ”这样的编号会更准确。

// --- 3. 构建 Hugo Front Matter (YAML 格式) ---

// 3.1. 定义用于处理YAML特殊字符的函数
const toYamlString = (value) => {
  if (value === undefined || value === null) return '""';
  // 确保摘要为单行，并对特殊字符进行转义
  let singleLineValue = String(value).replace(/\s+/g, ' ').trim();
  return JSON.stringify(singleLineValue);
};

const toYamlList = (arr) => {
  if (!Array.isArray(arr) || arr.length === 0) return '[]';
  // 使用JSON.stringify来安全地处理列表中的每个元素
  return '\n' + arr.map(item => `  - ${JSON.stringify(item)}`).join('\n');
}

// 3.2. 解析tags和main_topics字符串为数组
const tags = tagsString ? tagsString.split(',').map(tag => tag.trim()).filter(Boolean) : ['AI新闻', '早报']; // 默认标签更新
const main_topics = mainTopicsString ? mainTopicsString.split(',').map(topic => topic.trim()).filter(Boolean) : ['行业动态']; // 默认主题更新

// 3.3. 定义Front Matter的内容
const featuredImage = '/images/ai-report-default.png'; // 默认特色图片
const hugoDate = $now.toISO(); // 使用n8n内置的$now变量生成符合ISO 8601标准的日期

// 3.4. 拼接Front Matter字符串
const frontMatter = `---
title: ${toYamlString(title)}
date: ${hugoDate}
draft: false
featured_image: ${toYamlString(featuredImage)}
summary: ${toYamlString(summary || '本日AI内参极速早报。')}
tags: ${toYamlList(tags)}
main_topics: ${toYamlList(main_topics)}
selected_article_count: ${selected_article_count}
---
`;


// --- 4. 生成唯一且SEO友好的文件名 ---

const generateSlug = (str) => {
  if (!str) return '';
  // 这是一个更完整的slugify实现，能处理多种字符
  str = str.toString().toLowerCase().trim()
    .replace(/[\s\W-]+/g, '-') // 替换空格和非单词字符为-
    .replace(/--+/g, '-');      // 替换多个-为一个
  return str;
}

const generateUniqueFilename = (originalTitle) => {
  const datePrefix = $now.toFormat('yyyy-MM-dd');
  // 截取标题的一部分作为slug，避免文件名过长
  const titleSlug = generateSlug(originalTitle).substring(0, 50);
  // 返回一个结构清晰的文件名，确保文件名中包含日期且与标题相关
  // 例如: 2025-06-30-ai-zaobao.md 或 2025-06-30-mou-er-xian-cheng.md
  return `${datePrefix}-${titleSlug || 'ai-daily-brief'}.md`;
};

const finalFileName = generateUniqueFilename(title);


// --- 5. 组合并返回最终结果 ---

// 组合Front Matter和处理后的文章内容
const hugoArticle = frontMatter + '\n' + articleContentFormatted;

return {
  title: title,
  hugo_article: hugoArticle,
  fileName: finalFileName,
  report_summary: summary, // 这个 summary 现在是 LLM 生成的“今日焦点”
  created_at: hugoDate,
  selected_article_count: selected_article_count, // 现在是早报条目数量
  tags: tags, // 同时返回数组形式的tags和topics，方便后续可能的使用
  main_topics: main_topics
};
